-- Ngân hàng câu hỏi MẪU (133 câu Giải tích 1 + Đại số). Chạy SAU schema.sql.
-- Chạy lại an toàn: câu đã có sẽ được cập nhật nội dung.
on conflict (id) do update set mon=excluded.mon, chuong=excluded.chuong, do_kho=excluded.do_kho, kieu=excluded.kieu, de=excluded.de, lua=excluded.lua, dap=excluded.dap, giai=excluded.giai, dung_cho_cau_chung=excluded.dung_cho_cau_chung, updated_at=now();
