('GT1-001','GT1','GT1.1',1,'mc','Giới hạn $\lim\limits_{x\to 0}\dfrac{\sin x}{x}$ bằng','["$1$", "$0$", "$+\\infty$", "Không tồn tại"]'::jsonb,0,'Giới hạn cơ bản: khi $x\to0$ thì $\sin x\sim x$, nên $\dfrac{\sin x}{x}\to 1$.',true),
('GT1-002','GT1','GT1.1',1,'mc','$\lim\limits_{n\to\infty}\left(1+\dfrac{1}{n}\right)^{n}$ bằng','["$1$", "$e$", "$+\\infty$", "$0$"]'::jsonb,1,'Đây là định nghĩa số $e$. Dạng vô định $1^\infty$ không có nghĩa là kết quả bằng $1$.',true),
('GT1-003','GT1','GT1.1',1,'mc','Dãy $u_n=\dfrac{(-1)^n}{n}$','["phân kỳ vì dấu đổi liên tục", "hội tụ về $1$", "hội tụ về $0$", "hội tụ về $-1$"]'::jsonb,2,'$|u_n|=\dfrac1n\to0$ nên $u_n\to0$. Dấu đổi liên tục không cản trở hội tụ.',true),
('GT1-004','GT1','GT1.1',1,'mc','$\lim\limits_{x\to 0}\dfrac{e^{x}-1}{x}$ bằng','["$0$", "$e$", "$1$", "$+\\infty$"]'::jsonb,2,'VCB tương đương: $e^x-1\sim x$ khi $x\to0$, nên giới hạn bằng $1$.',true),
('GT1-005','GT1','GT1.1',2,'mc','Cho $f(x)=\dfrac{\sin x}{x}$ khi $x\ne0$ và $f(0)=a$. Hàm liên tục tại $0$ khi','["$a=1$", "$a=0$", "$a=-1$", "không có $a$ nào"]'::jsonb,0,'Liên tục tại $0$ khi $f(0)=\lim\limits_{x\to0}f(x)=1$.',true),
('GT1-006','GT1','GT1.1',2,'mc','$\lim\limits_{x\to 0^+} x\ln x$ bằng','["$-\\infty$", "$0$", "$1$", "$-1$"]'::jsonb,1,'Viết $x\ln x=\dfrac{\ln x}{1/x}$, dạng $\dfrac{\infty}{\infty}$. L''Hôpital: $\dfrac{1/x}{-1/x^2}=-x\to0$.',true),
('GT1-007','GT1','GT1.1',1,'tf','Mọi dãy số bị chặn đều hội tụ.','["Đúng", "Sai"]'::jsonb,1,'Phản ví dụ: $u_n=(-1)^n$ bị chặn nhưng phân kỳ. Bolzano–Weierstrass chỉ đảm bảo có một dãy con hội tụ.',true),
('GT1-008','GT1','GT1.1',1,'tf','Nếu $f$ liên tục trên $[a;b]$ và $f(a)f(b)<0$ thì phương trình $f(x)=0$ có nghiệm trong $(a;b)$.','["Đúng", "Sai"]'::jsonb,0,'Định lý giá trị trung gian (Bolzano–Cauchy).',true),
('GT1-009','GT1','GT1.1',2,'mc','Với $f(x)=\dfrac{|x|}{x}$, điểm $x=0$ là','["điểm gián đoạn loại 1 (bước nhảy)", "điểm gián đoạn khử được", "điểm gián đoạn loại 2", "điểm liên tục"]'::jsonb,0,'$f(0^+)=1$, $f(0^-)=-1$: hai giới hạn một phía hữu hạn nhưng khác nhau, nên là gián đoạn loại 1.',true),
('GT1-010','GT1','GT1.1',2,'mc','Khi $x\to0$, vô cùng bé nào tương đương với $x^2$?','["$1-\\cos x$", "$\\sin x$", "$1-\\cos(\\sqrt2\\,x)$", "$\\tan(x^3)$"]'::jsonb,2,'$1-\cos u\sim\dfrac{u^2}{2}$, với $u=\sqrt2x$ được $\dfrac{2x^2}{2}=x^2$.',true),
('GT1-011','GT1','GT1.2',1,'mc','$(\ln x)''$ bằng','["$\\dfrac{1}{x}$", "$\\ln x$", "$\\dfrac{1}{x\\ln 10}$", "$x\\ln x-x$"]'::jsonb,0,'Công thức cơ bản: $(\ln x)''=\dfrac1x$. Còn $\dfrac{1}{x\ln10}$ là đạo hàm của $\log_{10}x$.',true),
('GT1-012','GT1','GT1.2',1,'mc','$(\arctan x)''$ bằng','["$\\dfrac{1}{\\sqrt{1-x^2}}$", "$\\dfrac{1}{1+x^2}$", "$-\\dfrac{1}{1+x^2}$", "$\\dfrac{1}{1-x^2}$"]'::jsonb,1,'Bảng đạo hàm: $(\arctan x)''=\dfrac{1}{1+x^2}$. $\dfrac{1}{\sqrt{1-x^2}}$ là của $\arcsin x$.',true),
('GT1-013','GT1','GT1.2',2,'mc','Với $x>0$, $(x^x)''$ bằng','["$x\\cdot x^{x-1}$", "$x^x\\ln x$", "$x^x(\\ln x+1)$", "$x^x$"]'::jsonb,2,'$x^x=e^{x\ln x}$ nên $(x^x)''=e^{x\ln x}(\ln x+1)=x^x(\ln x+1)$.',true),
('GT1-014','GT1','GT1.2',1,'mc','Vi phân $d(\sin^2 x)$ bằng','["$\\sin 2x\\,dx$", "$2\\sin x\\,dx$", "$\\cos^2x\\,dx$", "$2\\cos x\\,dx$"]'::jsonb,0,'$d(\sin^2x)=2\sin x\cos x\,dx=\sin2x\,dx$.',true),
('GT1-015','GT1','GT1.2',1,'tf','Hàm khả vi tại $x_0$ thì liên tục tại $x_0$.','["Đúng", "Sai"]'::jsonb,0,'Khả vi kéo theo liên tục. Chiều ngược lại sai, ví dụ $|x|$ tại $0$.',true),
('GT1-016','GT1','GT1.2',1,'tf','Hàm $f(x)=|x|$ có đạo hàm tại $x=0$.','["Đúng", "Sai"]'::jsonb,1,'$f''_+(0)=1$, $f''_-(0)=-1$ khác nhau, nên không có đạo hàm tại $0$.',true),
('GT1-017','GT1','GT1.2',1,'mc','Đạo hàm cấp $n$ của $e^{2x}$ là','["$e^{2x}$", "$2n\\,e^{2x}$", "$2^n e^{2x}$", "$n!\\,e^{2x}$"]'::jsonb,2,'Mỗi lần đạo hàm nhân thêm $2$, sau $n$ lần được $2^ne^{2x}$.',true),
('GT1-018','GT1','GT1.2',2,'mc','Cho $x=t^2$, $y=t^3$ ($t\ne0$). Đạo hàm $y''_x$ bằng','["$\\dfrac{3t}{2}$", "$\\dfrac{2}{3t}$", "$\\dfrac{3t^2}{2}$", "$6t^3$"]'::jsonb,0,'$y''_x=\dfrac{y''_t}{x''_t}=\dfrac{3t^2}{2t}=\dfrac{3t}{2}$.',true),
('GT1-019','GT1','GT1.2',1,'mc','Với $f(x)=\sqrt x$, $f''(4)$ bằng','["$\\dfrac12$", "$\\dfrac14$", "$2$", "$\\dfrac18$"]'::jsonb,1,'$f''(x)=\dfrac{1}{2\sqrt x}$ nên $f''(4)=\dfrac{1}{2\cdot2}=\dfrac14$.',true),
('GT1-020','GT1','GT1.3',1,'mc','Khai triển Maclaurin của $\cos x$ đến $x^4$ là','["$1-\\dfrac{x^2}{2}+\\dfrac{x^4}{24}$", "$1+\\dfrac{x^2}{2}+\\dfrac{x^4}{24}$", "$1-\\dfrac{x^2}{2}+\\dfrac{x^4}{4}$", "$x-\\dfrac{x^3}{6}$"]'::jsonb,0,'$\cos x=\sum (-1)^k\dfrac{x^{2k}}{(2k)!}$: $1-\dfrac{x^2}{2!}+\dfrac{x^4}{4!}+o(x^4)$.',true),
('GT1-021','GT1','GT1.3',2,'mc','$\lim\limits_{x\to0}\dfrac{x-\sin x}{x^3}$ bằng','["$0$", "$\\dfrac16$", "$\\dfrac13$", "$-\\dfrac16$"]'::jsonb,1,'$\sin x=x-\dfrac{x^3}{6}+o(x^3)$ nên $x-\sin x\sim\dfrac{x^3}{6}$.',true),
('GT1-022','GT1','GT1.3',1,'mc','$\lim\limits_{x\to+\infty}\dfrac{\ln x}{x}$ bằng','["$0$", "$1$", "$+\\infty$", "Không tồn tại"]'::jsonb,0,'L''Hôpital: $\dfrac{1/x}{1}\to0$. Hàm $\ln$ tăng chậm hơn mọi lũy thừa dương.',true),
('GT1-023','GT1','GT1.3',2,'mc','$\lim\limits_{x\to0}\dfrac{\tan x-x}{x^3}$ bằng','["$\\dfrac16$", "$0$", "$\\dfrac13$", "$1$"]'::jsonb,2,'$\tan x=x+\dfrac{x^3}{3}+o(x^3)$ nên giới hạn bằng $\dfrac13$.',true),
('GT1-024','GT1','GT1.3',1,'tf','Nếu $f''(x_0)=0$ thì $x_0$ là điểm cực trị của $f$.','["Đúng", "Sai"]'::jsonb,1,'Phản ví dụ: $f(x)=x^3$ có $f''(0)=0$ nhưng $0$ không là cực trị. $f''(x_0)=0$ chỉ là điều kiện cần.',true),
('GT1-025','GT1','GT1.3',1,'mc','Hàm $y=x^3-3x$ đạt cực đại tại','["$x=-1$", "$x=1$", "$x=0$", "$x=\\sqrt3$"]'::jsonb,0,'$y''=3x^2-3=0\Leftrightarrow x=\pm1$; $y''''=6x$, $y''''(-1)=-6<0$ nên cực đại tại $x=-1$.',true),
('GT1-026','GT1','GT1.3',2,'mc','Điểm uốn của đồ thị $y=x^3-3x^2+2$ là','["$(0;2)$", "$(1;0)$", "$(2;-2)$", "$(1;2)$"]'::jsonb,1,'$y''''=6x-6$ đổi dấu tại $x=1$, $y(1)=0$. Điểm $(2;-2)$ là điểm cực tiểu.',true),
('GT1-027','GT1','GT1.3',1,'mc','Tiệm cận ngang của đồ thị $y=\dfrac{2x+1}{x-3}$ là','["$x=3$", "$y=-\\dfrac13$", "$y=2$", "$y=\\dfrac12$"]'::jsonb,2,'$\lim\limits_{x\to\pm\infty}y=2$. Còn $x=3$ là tiệm cận đứng.',true),
('GT1-028','GT1','GT1.4',1,'mc','$\displaystyle\int\frac{dx}{x}$ bằng','["$\\ln|x|+C$", "$-\\dfrac{1}{x^2}+C$", "$\\dfrac1x+C$", "$x\\ln x+C$"]'::jsonb,0,'$(\ln|x|)''=\dfrac1x$ với mọi $x\ne0$.',true),
('GT1-029','GT1','GT1.4',2,'mc','$\displaystyle\int xe^x\,dx$ bằng','["$xe^x+C$", "$(x-1)e^x+C$", "$(x+1)e^x+C$", "$\\dfrac{x^2}{2}e^x+C$"]'::jsonb,1,'Từng phần: $u=x$, $dv=e^xdx$: $xe^x-\int e^xdx=(x-1)e^x+C$.',true),
('GT1-030','GT1','GT1.4',1,'mc','$\displaystyle\int\frac{dx}{1+x^2}$ bằng','["$\\ln(1+x^2)+C$", "$\\arcsin x+C$", "$\\arctan x+C$", "$\\dfrac{1}{2x}\\ln(1+x^2)+C$"]'::jsonb,2,'Bảng nguyên hàm cơ bản.',true),
('GT1-031','GT1','GT1.4',2,'mc','$\displaystyle\int\sin^2x\,dx$ bằng','["$\\dfrac x2-\\dfrac{\\sin2x}{4}+C$", "$\\dfrac{\\sin^3x}{3}+C$", "$\\dfrac x2+\\dfrac{\\sin2x}{4}+C$", "$-\\cos^2x+C$"]'::jsonb,0,'Hạ bậc: $\sin^2x=\dfrac{1-\cos2x}{2}$, nguyên hàm $\dfrac x2-\dfrac{\sin2x}{4}+C$.',true),
('GT1-032','GT1','GT1.4',2,'mc','$\displaystyle\int\frac{dx}{x^2-1}$ bằng','["$\\dfrac12\\ln\\left|\\dfrac{x+1}{x-1}\\right|+C$", "$\\dfrac12\\ln\\left|\\dfrac{x-1}{x+1}\\right|+C$", "$\\ln|x^2-1|+C$", "$\\arctan x+C$"]'::jsonb,1,'$\dfrac{1}{x^2-1}=\dfrac12\left(\dfrac{1}{x-1}-\dfrac{1}{x+1}\right)$ nên nguyên hàm là $\dfrac12\ln\left|\dfrac{x-1}{x+1}\right|+C$.',false),
('GT1-033','GT1','GT1.4',1,'tf','Mọi hàm liên tục trên một khoảng đều có nguyên hàm trên khoảng đó.','["Đúng", "Sai"]'::jsonb,0,'Có thể lấy $F(x)=\int_{a}^{x}f(t)\,dt$ (định lý cơ bản của giải tích).',true),
('GT1-034','GT1','GT1.4',1,'mc','$\displaystyle\int\frac{\ln x}{x}\,dx$ bằng','["$\\dfrac{\\ln^2x}{2}+C$", "$\\ln^2x+C$", "$\\ln(\\ln x)+C$", "$\\dfrac{x\\ln x}{2}+C$"]'::jsonb,0,'Đặt $t=\ln x$, $dt=\dfrac{dx}{x}$: $\int t\,dt=\dfrac{t^2}{2}+C$.',true),
('GT1-035','GT1','GT1.5',1,'mc','$\displaystyle\int_0^1x^2\,dx$ bằng','["$\\dfrac12$", "$\\dfrac13$", "$1$", "$\\dfrac23$"]'::jsonb,1,'$\left.\dfrac{x^3}{3}\right|_0^1=\dfrac13$.',true),
('GT1-036','GT1','GT1.5',1,'mc','$\displaystyle\int_0^{\pi}\sin x\,dx$ bằng','["$0$", "$-2$", "$2$", "$1$"]'::jsonb,2,'$\left.-\cos x\right|_0^{\pi}=-(-1)+1=2$.',true),
('GT1-037','GT1','GT1.5',1,'mc','$\displaystyle\int_{-1}^{1}x^3\cos x\,dx$ bằng','["$0$", "$2\\cos1$", "$1$", "$-1$"]'::jsonb,0,'$x^3\cos x$ là hàm lẻ, cận đối xứng nên tích phân bằng $0$.',true),
('GT1-038','GT1','GT1.5',2,'mc','$\dfrac{d}{dx}\displaystyle\int_0^{x^2}e^{t^2}\,dt$ bằng','["$e^{x^4}$", "$e^{x^2}$", "$2x\\,e^{x^4}$", "$2x\\,e^{x^2}$"]'::jsonb,2,'$\left(\int_0^{u(x)}f\right)''=f(u(x))\,u''(x)=e^{x^4}\cdot2x$.',true),
