('GT1-040','GT1','GT1.5',2,'mc','$\displaystyle\int_0^1\frac{dx}{\sqrt x}$','["phân kỳ vì hàm không bị chặn", "hội tụ, bằng $2$", "hội tụ, bằng $\\dfrac12$", "hội tụ, bằng $1$"]'::jsonb,1,'Tích phân suy rộng loại 2 với $p=\tfrac12<1$ hội tụ: $\left.2\sqrt x\right|_0^1=2$.',true),
('GT1-041','GT1','GT1.5',1,'mc','Diện tích hình phẳng giới hạn bởi $y=x^2$ và $y=x$ bằng','["$\\dfrac16$", "$\\dfrac13$", "$\\dfrac12$", "$\\dfrac56$"]'::jsonb,0,'Giao tại $x=0$, $x=1$: $S=\int_0^1(x-x^2)dx=\dfrac12-\dfrac13=\dfrac16$.',true),
('GT1-042','GT1','GT1.5',2,'tf','Tích phân $\displaystyle\int_1^{+\infty}\frac{\sin^2x}{x^2}\,dx$ hội tụ.','["Đúng", "Sai"]'::jsonb,0,'$0\le\dfrac{\sin^2x}{x^2}\le\dfrac1{x^2}$ và $\int_1^{+\infty}\dfrac{dx}{x^2}$ hội tụ, nên hội tụ theo tiêu chuẩn so sánh.',true),
('GT1-043','GT1','GT1.5',2,'mc','Quay miền $0\le y\le\sqrt x$, $0\le x\le1$ quanh trục $Ox$. Thể tích bằng','["$\\dfrac{\\pi}{3}$", "$\\dfrac{\\pi}{2}$", "$\\pi$", "$\\dfrac{2\\pi}{3}$"]'::jsonb,1,'$V=\pi\int_0^1(\sqrt x)^2dx=\pi\int_0^1x\,dx=\dfrac{\pi}{2}$.',true),
('GT1-044','GT1','GT1.5',1,'mc','$\displaystyle\int_0^{2}|x-1|\,dx$ bằng','["$0$", "$1$", "$2$", "$\\dfrac12$"]'::jsonb,1,'Tách cận tại $1$: $\int_0^1(1-x)dx+\int_1^2(x-1)dx=\dfrac12+\dfrac12=1$.',true),
('GT1-045','GT1','GT1.6',1,'mc','Với $f(x,y)=x^2y+y^3$, $f''_x$ bằng','["$2xy$", "$x^2+3y^2$", "$2xy+3y^2$", "$2x$"]'::jsonb,0,'Coi $y$ là hằng số: $(x^2y)''_x=2xy$, $(y^3)''_x=0$.',true),
('GT1-046','GT1','GT1.6',2,'mc','Với $f(x,y)=e^{xy}$, $f''''_{xy}$ bằng','["$xy\\,e^{xy}$", "$(1+xy)\\,e^{xy}$", "$e^{xy}$", "$x^2e^{xy}$"]'::jsonb,1,'$f''_x=ye^{xy}$; đạo hàm theo $y$: $e^{xy}+xy\,e^{xy}$.',true),
('GT1-047','GT1','GT1.6',1,'mc','Vi phân toàn phần của $z=x^2+xy$ là','["$dz=(2x+y)\\,dx+x\\,dy$", "$dz=2x\\,dx+y\\,dy$", "$dz=(2x+y)\\,dx+y\\,dy$", "$dz=(2x+y)(dx+dy)$"]'::jsonb,0,'$dz=z''_xdx+z''_ydy$ với $z''_x=2x+y$, $z''_y=x$.',true),
('GT1-048','GT1','GT1.6',2,'mc','$\lim\limits_{(x,y)\to(0,0)}\dfrac{xy}{x^2+y^2}$','["bằng $0$", "bằng $\\dfrac12$", "bằng $1$", "không tồn tại"]'::jsonb,3,'Theo đường $y=kx$: giới hạn bằng $\dfrac{k}{1+k^2}$, phụ thuộc $k$, nên không tồn tại.',true),
('GT1-049','GT1','GT1.6',2,'tf','Nếu $f(x,y)$ có các đạo hàm riêng tại $(x_0,y_0)$ thì $f$ khả vi tại đó.','["Đúng", "Sai"]'::jsonb,1,'Có đạo hàm riêng chưa đủ. Ví dụ $f=\dfrac{xy}{x^2+y^2}$, $f(0,0)=0$ có $f''_x=f''_y=0$ tại gốc nhưng không liên tục.',true),
('GT1-050','GT1','GT1.6',2,'mc','$\lim\limits_{(x,y)\to(0,0)}\dfrac{x^2y}{x^2+y^2}$ bằng','["$0$", "không tồn tại", "$1$", "$\\dfrac12$"]'::jsonb,0,'$\left|\dfrac{x^2y}{x^2+y^2}\right|\le|y|\to0$.',true),
('GT1-051','GT1','GT1.6',1,'mc','Gradient của $f=x^2+y^2$ tại $(1;2)$ là','["$(1;2)$", "$(2;4)$", "$(4;2)$", "$(2;2)$"]'::jsonb,1,'$\nabla f=(2x;2y)=(2;4)$ tại $(1;2)$.',true),
('GT1-052','GT1','GT1.7',1,'mc','Hàm $f(x,y)=x^2+y^2-2x$','["đạt cực tiểu tại $(1;0)$", "đạt cực đại tại $(1;0)$", "đạt cực tiểu tại $(0;0)$", "không có cực trị"]'::jsonb,0,'$f=(x-1)^2+y^2-1\ge-1$, dấu bằng tại $(1;0)$.',true),
('GT1-053','GT1','GT1.7',2,'mc','Với $f(x,y)=xy$, điểm $(0;0)$ là','["điểm cực tiểu", "điểm cực đại", "điểm dừng nhưng không là cực trị", "không phải điểm dừng"]'::jsonb,2,'$f''_x=y$, $f''_y=x$ triệt tiêu tại gốc. $AC-B^2=0-1<0$ nên là điểm yên ngựa.',true),
('GT1-054','GT1','GT1.7',2,'mc','Giá trị lớn nhất của $x+y$ với điều kiện $x^2+y^2=2$ là','["$\\sqrt2$", "$2$", "$1$", "$4$"]'::jsonb,1,'Lagrange: $1=2\lambda x$, $1=2\lambda y$ nên $x=y=\pm1$. Lớn nhất bằng $2$ tại $(1;1)$.',true),
('GT1-055','GT1','GT1.7',1,'tf','Tại điểm dừng $M$, nếu $AC-B^2<0$ thì $M$ không là điểm cực trị ($A=f''''_{xx}$, $B=f''''_{xy}$, $C=f''''_{yy}$).','["Đúng", "Sai"]'::jsonb,0,'Định lý điều kiện đủ: $AC-B^2<0$ thì không có cực trị (điểm yên ngựa).',true),
('GT1-056','GT1','GT1.7',1,'tf','Tại điểm dừng, nếu $AC-B^2=0$ thì hàm chắc chắn không có cực trị tại đó.','["Đúng", "Sai"]'::jsonb,1,'Trường hợp $AC-B^2=0$ chưa kết luận được. Ví dụ $x^4+y^4$ có cực tiểu tại gốc dù $AC-B^2=0$.',true),
('GT1-057','GT1','GT1.7',1,'mc','Giá trị nhỏ nhất của $x^2+y^2$ với điều kiện $x+y=2$ là','["$2$", "$4$", "$1$", "$\\sqrt2$"]'::jsonb,0,'Thế $y=2-x$: $2x^2-4x+4=2(x-1)^2+2\ge2$, đạt tại $(1;1)$.',true),
('GT1-058','GT1','GT1.7',3,'mc','Với $f(x,y)=x^3+y^3-3xy$, tại điểm $(1;1)$ hàm','["đạt cực tiểu", "đạt cực đại", "không đạt cực trị", "không có điểm dừng ở đó"]'::jsonb,0,'$f''_x=3x^2-3y$, $f''_y=3y^2-3x$ triệt tiêu tại $(1;1)$. $A=6$, $B=-3$, $C=6$, $AC-B^2=27>0$, $A>0$ nên cực tiểu.',false),
('GT1-B01','GT1','GT1.4',2,'buocsai','Tính $\displaystyle\int x\cos x\,dx$. Bước nào sai?','["Đặt $u=x$, $dv=\\cos x\\,dx$.", "Suy ra $du=dx$, $v=\\sin x$.", "$\\displaystyle\\int x\\cos x\\,dx=x\\sin x-\\int\\sin x\\,dx$.", "$=x\\sin x-\\cos x+C$."]'::jsonb,3,'$-\int\sin x\,dx=-(-\cos x)=+\cos x$. Đúng là $x\sin x+\cos x+C$.',false),
('GT1-B02','GT1','GT1.3',2,'buocsai','Tính $\lim\limits_{x\to0}\dfrac{1-\cos x}{x^2}$. Bước nào sai?','["Dạng $\\dfrac00$, áp dụng L''Hôpital.", "$=\\lim\\limits_{x\\to0}\\dfrac{-\\sin x}{2x}$.", "$=-\\dfrac12\\lim\\limits_{x\\to0}\\dfrac{\\sin x}{x}$.", "$=-\\dfrac12$."]'::jsonb,1,'$(1-\cos x)''=\sin x$ (không có dấu trừ). Kết quả đúng là $\dfrac12$.',false),
('GT1-B03','GT1','GT1.2',1,'buocsai','Tính đạo hàm của $y=\sin(x^2)$. Bước nào sai?','["Đặt $u=x^2$, khi đó $y=\\sin u$.", "$y''_u=\\cos u$.", "$y''_x=y''_u=\\cos(x^2)$.", "Vậy $y''=\\cos(x^2)$."]'::jsonb,2,'Quy tắc hàm hợp: $y''_x=y''_u\cdot u''_x=2x\cos(x^2)$.',false),
('GT1-B04','GT1','GT1.5',3,'buocsai','Tính $\displaystyle\int_{-1}^{1}\frac{dx}{x^2}$. Bước nào sai?','["Một nguyên hàm của $\\dfrac{1}{x^2}$ là $-\\dfrac1x$.", "$\\displaystyle\\int_{-1}^{1}\\frac{dx}{x^2}=\\left[-\\frac1x\\right]_{-1}^{1}$.", "$=-1-1=-2$.", "Vậy tích phân bằng $-2$."]'::jsonb,1,'Hàm không xác định tại $x=0\in[-1;1]$: đây là tích phân suy rộng, không dùng Newton–Leibniz trực tiếp. Tách tại $0$ thì phân kỳ. (Dấu hiệu nghi ngờ: hàm dương mà tích phân âm!)',false),
('GT1-B05','GT1','GT1.7',2,'buocsai','Tìm cực trị của $f(x,y)=x^2-y^2$. Bước nào sai?','["$f''_x=2x$, $f''_y=-2y$.", "Điểm dừng duy nhất là $(0;0)$.", "$A=2$, $B=0$, $C=-2$, nên $AC-B^2=-4$.", "Vì $A>0$ nên $(0;0)$ là điểm cực tiểu."]'::jsonb,3,'Chỉ xét dấu của $A$ khi $AC-B^2>0$. Ở đây $AC-B^2<0$ nên $(0;0)$ là điểm yên ngựa, không có cực trị.',false),
('GT1-B06','GT1','GT1.5',1,'buocsai','Tính $\displaystyle\int_0^1 2x\,e^{x^2}dx$. Bước nào sai?','["Đặt $t=x^2$, $dt=2x\\,dx$.", "Đổi cận: $x=0\\Rightarrow t=0$; $x=1\\Rightarrow t=1$.", "Tích phân $=\\displaystyle\\int_0^1e^t\\,dt$.", "$=\\left.e^t\\right|_0^1=e$."]'::jsonb,3,'$\left.e^t\right|_0^1=e-e^0=e-1$.',false),
