('DS-050','DS','DS.6',1,'mc','Tích các trị riêng (kể cả bội, trên $\mathbb C$) của $A$ bằng','["$\\det A$", "$\\operatorname{tr}A$", "$r(A)$", "$1$"]'::jsonb,0,'Thay $\lambda=0$ vào $\det(A-\lambda I)=\prod(\lambda_i-\lambda)$ được $\det A=\prod\lambda_i$.',true),
('DS-051','DS','DS.6',1,'mc','$A$ có trị riêng $\lambda$ ứng với vectơ riêng $v$. Khi đó $A^2$ có trị riêng','["$2\\lambda$", "$\\lambda^2$", "$\\lambda$", "$\\sqrt\\lambda$"]'::jsonb,1,'$A^2v=A(\lambda v)=\lambda^2v$.',true),
('DS-052','DS','DS.6',1,'tf','Ma trận vuông cấp $n$ có $n$ trị riêng thực phân biệt thì chéo hoá được trên $\mathbb R$.','["Đúng", "Sai"]'::jsonb,0,'Các vectơ riêng ứng với trị riêng phân biệt độc lập tuyến tính, đủ $n$ vectơ.',true),
('DS-053','DS','DS.6',1,'tf','Mọi ma trận vuông thực đều chéo hoá được trên $\mathbb R$.','["Đúng", "Sai"]'::jsonb,1,'Ví dụ $\begin{pmatrix}1&1\\0&1\end{pmatrix}$ chỉ có một vectơ riêng độc lập.',true),
('DS-054','DS','DS.6',2,'mc','Ma trận $\begin{pmatrix}1&1\\0&1\end{pmatrix}$','["không chéo hoá được", "chéo hoá được", "có hai trị riêng phân biệt", "có trị riêng $0$"]'::jsonb,0,'Trị riêng kép $\lambda=1$ nhưng $\dim\operatorname{Ker}(A-I)=1<2$.',true),
('DS-055','DS','DS.6',1,'mc','Một vectơ riêng ứng với $\lambda=3$ của $\begin{pmatrix}3&0\\0&1\end{pmatrix}$ là','["$(0;1)$", "$(1;0)$", "$(1;1)$", "$(3;1)$"]'::jsonb,1,'$A(1;0)^T=(3;0)^T=3(1;0)^T$.',true),
('DS-056','DS','DS.7',1,'mc','Ma trận đối xứng của dạng toàn phương $q=x^2+4xy+3y^2$ là','["$\\begin{pmatrix}1&2\\\\2&3\\end{pmatrix}$", "$\\begin{pmatrix}1&4\\\\4&3\\end{pmatrix}$", "$\\begin{pmatrix}1&4\\\\0&3\\end{pmatrix}$", "$\\begin{pmatrix}1&2\\\\2&-3\\end{pmatrix}$"]'::jsonb,0,'Hệ số của $xy$ chia đôi cho hai vị trí đối xứng: $a_{12}=a_{21}=2$.',true),
('DS-057','DS','DS.7',1,'mc','Tiêu chuẩn Sylvester: dạng toàn phương xác định dương khi và chỉ khi','["mọi định thức con chính góc trái đều dương", "mọi phần tử đường chéo đều dương", "định thức của ma trận dương", "vết của ma trận dương"]'::jsonb,0,'$D_1>0, D_2>0,\dots,D_n>0$.',true),
('DS-058','DS','DS.7',1,'tf','Dạng toàn phương xác định dương khi và chỉ khi mọi trị riêng của ma trận đối xứng của nó đều dương.','["Đúng", "Sai"]'::jsonb,0,'Đưa về dạng chính tắc bằng phép biến đổi trực giao: $q=\sum\lambda_iy_i^2$.',true),
('DS-059','DS','DS.7',1,'mc','Tích vô hướng chính tắc của $u=(1;2;-1)$ và $v=(3;0;1)$ là','["$2$", "$4$", "$0$", "$-2$"]'::jsonb,0,'$1\cdot3+2\cdot0+(-1)\cdot1=2$.',true),
('DS-060','DS','DS.7',1,'mc','Độ dài (chuẩn Euclid) của $(1;2;2)$ là','["$5$", "$3$", "$9$", "$\\sqrt5$"]'::jsonb,1,'$\sqrt{1+4+4}=3$.',true),
('DS-061','DS','DS.7',1,'tf','Trong không gian Euclid, hai vectơ khác $0$ và trực giao với nhau thì độc lập tuyến tính.','["Đúng", "Sai"]'::jsonb,0,'Nếu $au+bv=0$, nhân vô hướng với $u$ được $a\|u\|^2=0\Rightarrow a=0$; tương tự $b=0$.',true),
('DS-062','DS','DS.7',1,'mc','Bất đẳng thức Cauchy–Schwarz phát biểu','["$|\\langle u,v\\rangle|\\le\\|u\\|\\,\\|v\\|$", "$|\\langle u,v\\rangle|\\ge\\|u\\|\\,\\|v\\|$", "$|\\langle u,v\\rangle|=\\|u\\|\\,\\|v\\|$", "$\\|u+v\\|\\ge\\|u\\|+\\|v\\|$"]'::jsonb,0,'Dấu bằng xảy ra khi và chỉ khi $u,v$ phụ thuộc tuyến tính.',true),
('DS-063','DS','DS.7',1,'mc','$Q$ là ma trận trực giao. Khi đó $Q^{-1}$ bằng','["$Q$", "$Q^T$", "$-Q$", "$(\\det Q)\\,Q$"]'::jsonb,1,'Định nghĩa: $Q^TQ=I$.',true),
('DS-B01','DS','DS.3',2,'buocsai','Tính $\det\begin{pmatrix}1&2&0\\0&1&3\\2&0&1\end{pmatrix}$ bằng khai triển theo hàng 1. Bước nào sai?','["$\\det=1\\cdot A_{11}+2\\cdot A_{12}+0\\cdot A_{13}$ ($A_{ij}$ là phần bù đại số).", "$A_{11}=\\begin{vmatrix}1&3\\\\0&1\\end{vmatrix}=1$.", "$A_{12}=\\begin{vmatrix}0&3\\\\2&1\\end{vmatrix}=-6$.", "$\\det=1\\cdot1+2\\cdot(-6)=-11$."]'::jsonb,2,'Quên dấu $(-1)^{1+2}$: $A_{12}=-\begin{vmatrix}0&3\\2&1\end{vmatrix}=6$. Định thức đúng là $1+12=13$.',false),
('DS-B02','DS','DS.3',1,'buocsai','Tìm nghịch đảo của $A=\begin{pmatrix}2&1\\5&3\end{pmatrix}$. Bước nào sai?','["$\\det A=2\\cdot3-1\\cdot5=1\\ne0$ nên $A$ khả nghịch.", "Công thức $A^{-1}=\\dfrac{1}{\\det A}\\begin{pmatrix}d&-b\\\\-c&a\\end{pmatrix}$.", "$A^{-1}=\\begin{pmatrix}3&1\\\\5&2\\end{pmatrix}$.", "Vậy $A^{-1}$ như trên."]'::jsonb,2,'Quên đổi dấu hai phần tử phụ: đúng là $\begin{pmatrix}3&-1\\-5&2\end{pmatrix}$.',false),
('DS-B03','DS','DS.2',1,'buocsai','Tính $(1+i)^2$. Bước nào sai?','["$(1+i)^2=1+2i+i^2$.", "Vì $i^2=1$ nên $(1+i)^2=1+2i+1$.", "$=2+2i$.", "Do đó $|(1+i)^2|=2\\sqrt2$."]'::jsonb,1,'$i^2=-1$, nên $(1+i)^2=2i$ và $|2i|=2$.',false),
('DS-B04','DS','DS.6',2,'buocsai','Tìm trị riêng của $A=\begin{pmatrix}4&1\\2&3\end{pmatrix}$. Bước nào sai?','["Phương trình đặc trưng $\\det(A-\\lambda I)=0$.", "$(4-\\lambda)(3-\\lambda)-2=0$.", "$\\lambda^2-7\\lambda+14=0$.", "$\\Delta<0$ nên $A$ không có trị riêng thực."]'::jsonb,2,'$(4-\lambda)(3-\lambda)-2=\lambda^2-7\lambda+10$, nghiệm $\lambda=2$, $\lambda=5$.',false),
('DS-B05','DS','DS.3',1,'buocsai','Tìm hạng của ma trận có các hàng $(1;2;3)$, $(2;4;6)$, $(1;0;1)$. Bước nào sai?','["$h_2\\to h_2-2h_1$: hàng 2 thành $(0;0;0)$.", "$h_3\\to h_3-h_1$: hàng 3 thành $(0;-2;-2)$.", "Đổi chỗ, ma trận bậc thang có 2 hàng khác $0$.", "Vậy $r(A)=3$."]'::jsonb,3,'Hạng bằng số hàng khác $0$ của dạng bậc thang: $r(A)=2$.',false),
('DS-B06','DS','DS.5',1,'buocsai','Kiểm tra $f(x;y)=(x+1;\ y)$ có tuyến tính không. Bước nào sai?','["Lấy $u=(x_1;y_1)$, $v=(x_2;y_2)$.", "$f(u+v)=(x_1+x_2+1;\\ y_1+y_2)$.", "$f(u)+f(v)=(x_1+x_2+2;\\ y_1+y_2)$.", "Vì $f(u+v)=f(u)+f(v)$ nên $f$ tuyến tính."]'::jsonb,3,'Hai kết quả khác nhau ($+1$ và $+2$), nên $f$ KHÔNG tuyến tính. Cũng thấy ngay $f(0)=(1;0)\ne0$.',false)
